import coreSeed from '../../platform/onboarding/lib/seed.json'
import expansionSeed from '../../platform/onboarding/lib/expansion-seed.json'
import demoAuthoritySeed from '../../platform/onboarding/lib/demo-authority-seed.json'
import { applyDemoAuthoritySeed } from './demo-authority-runtime'
import { applyCoreSeed, applyExpansionSeed, type SeedContext } from './seed-runtime'

export async function runRealEstateOnboarding(context: SeedContext, template: 'full' | 'minimal' = 'full') {
  const core = await applyCoreSeed(context, coreSeed, template)
  const selectedAgents = new Set(coreSeed.sections.agents.items.filter(item => item.templates.includes(template)).map(item => item.data.email))
  const selectedProperties = new Set(coreSeed.sections.properties.items.filter(item => item.templates.includes(template)).map(item => item.data.slug))
  await applyDemoAuthoritySeed(context, { ...demoAuthoritySeed,
    practitioners: demoAuthoritySeed.practitioners.filter(item => selectedAgents.has(item.email)),
    listings: demoAuthoritySeed.listings.filter(item => selectedProperties.has(item.propertySlug)),
  })
  const expansion = template === 'full' ? await applyExpansionSeed(context, expansionSeed) : { created: 0, skipped: 0, total: 0 }
  return { core, expansion }
}
