import type { Context } from '.keystone/types'

import { runRealEstateOnboarding } from '../onboarding/run-onboarding'
import { activeBrokerageIds } from '../access'
import { freshOperatorCommandContext } from '../lib/commandContext'
import type { SeedContext } from '../onboarding/seed-runtime'

type SeedResult = {
  core: { created: number; skipped: number; total: number }
  expansion: { created: number; skipped: number; total: number }
}

type SeedRunner = (context: SeedContext) => Promise<SeedResult>

function onboardingSession(context: Context) {
  const session = context.session as any
  const fixtureMembership = session?.data?.brokerageMemberships?.find((membership: any) =>
    membership.status === 'active' &&
    membership.brokerage?.status === 'active' &&
    membership.brokerage?.slug === 'juniper-realty' &&
    ['owner', 'admin'].includes(membership.membershipRole)
  )
  if (!session?.itemId || !session.data?.role?.canManageOnboarding || !fixtureMembership || !activeBrokerageIds(session).includes(fixtureMembership.brokerage.id)) {
    throw new Error('Juniper Realty owner or administrator access is required for this fixture onboarding.')
  }
  return session
}

export async function runRealEstateOnboardingTransaction(
  context: Context,
  seedRunner: SeedRunner | undefined = undefined,
  template: 'full' | 'minimal' = 'full'
) {
  const session = onboardingSession(context)

  return context.transaction(async transactionContext => {
    const sessionContext = await freshOperatorCommandContext(transactionContext.withSession(session))
    const currentSession = onboardingSession(sessionContext)
    const sudo = sessionContext.sudo()

    // Join the brokerage-first command protocol before the narrower onboarding lock.
    await sudo.prisma.$executeRawUnsafe('SELECT pg_advisory_xact_lock(hashtext($1))', 'onboarding:juniper-realty')
    await sudo.db.User.updateOne({
      where: { id: currentSession.itemId },
      data: { onboardingStatus: 'in_progress' },
    })

    const result = await (seedRunner || ((seedContext: SeedContext) => runRealEstateOnboarding(seedContext, template)))(sudo as unknown as SeedContext)

    await sudo.db.User.updateOne({
      where: { id: currentSession.itemId },
      data: { onboardingStatus: 'completed' },
    })

    return { completed: true, status: 'completed', ...result }
  }, { timeout: 120_000 })
}

export async function runRealEstateOnboardingMutation(
  _root: unknown,
  { template = 'full' }: { template?: string },
  context: Context
) {
  if (template !== 'full' && template !== 'minimal') throw new Error('Invalid brokerage setup template.')
  return runRealEstateOnboardingTransaction(context, undefined, template)
}

export async function dismissRealEstateOnboarding(
  _root: unknown,
  _args: Record<string, never>,
  context: Context
) {
  const session = onboardingSession(context)
  await context.sudo().db.User.updateOne({
    where: { id: session.itemId },
    data: { onboardingStatus: 'dismissed' },
  })
  return { completed: false, status: 'dismissed', core: null, expansion: null }
}
